"""SELU activation: scale * (max(0,x) + min(0, alpha*(exp(x)-1)))."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '27_SELU_',
    'batch': 4096,
    'dim': 16384,
    'alpha': 1.6732632423543772848170429916717,
