    key = jax.random.key(0)
    x = jax.random.uniform(key, (CONFIG['batch'], CONFIG['dim']), dtype=dtype)
    return (x,)


def workload(x):
    alpha = jnp.asarray(CONFIG['alpha'], dtype=x.dtype)
